source='''from collections import deque

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    color_at = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            marker_colors = set()
            while queue:
                x, y = queue.popleft()
                cells.append((x, y))
                if grid[x][y] > 1:
                    marker_colors.add(grid[x][y])
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        queue.append((nx, ny))
            if marker_colors:
                color = next(iter(marker_colors))
                for x, y in cells:
                    color_at[(x, y)] = color
    for r in range(1, rows - 1):
        for c in range(1, cols - 1):
            if all(grid[x][y] != 0 for x in range(r - 1, r + 2) for y in range(c - 1, c + 2)) and (r, c) in color_at:
                out[r][c] = color_at[(r, c)]
    return out
'''
